from pathlib import Path
p=Path('outputs/ROMDex/tests/rom-workspace.test.mjs');s=p.read_text()+'''
test('fresh MAPDex has no testbed selected and catalog changes clear prior-source UI drafts',async t=>{const {importer}=await setup(t);assert.equal(importer.state.selected,null);assert.deepEqual(importer.state.headers,[]);importer.state.source={source:{sha256:'a'.repeat(64)},maps:[{headerId:1,section:1,name:'OLD'}]};importer.state.selected='section:1';importer.state.positions={'section:1':{drafts:{mapName:'Old draft'}}};importer.state.position=importer.state.positions['section:1'];let worker;importer.workerFactory=()=>{worker=new EventEmitter();return worker};await importer.start({mode:'catalog',file:'fixture.nds'});const done=importer.job.done;worker.emit('message',{result:{source:{sha256:'b'.repeat(64)},maps:[{headerId:9,section:7,name:'NEW',label:'New Place'}]}});await done;assert.equal(importer.state.selected,null);assert.deepEqual(importer.state.headers,[]);assert.deepEqual(importer.state.positions,{});assert.equal(importer.state.position,null);await importer.dispatch('select',{id:'section:7'});assert.deepEqual(importer.state.headers,[9]);});
test('map selection keeps each group own UI position instead of reusing another map draft',async t=>{const {importer}=await prepared(t);importer.state.source.maps.push({headerId:9,section:7,name:'Other'});await importer.dispatch('position',{drafts:{mapName:'Local unfinished name'}});await importer.dispatch('select',{id:'section:7'});assert.equal(importer.state.position,null);assert.equal(importer.ready(),false);await importer.dispatch('select',{id:'section:128'});assert.equal(importer.state.position.drafts.mapName,'Local unfinished name');assert.equal(importer.ready(),true);});
''';p.write_text(s)
